from author_helpers import Draft
b=Draft(23)
b.concept('compute_term','Compute C term','Canonical typed compute composition generated exactly by C.of, C.id, C.compose, C.edge, workflow.C, C.batch and C.retry; transform/evaluate/consequence is bootstrap algebra data rather than a closed stage ontology.',[(0,41,46)])
b.concept('stage_leaf','Atomic C-call stage','One C.of<A,B,Role,Fibre> leaf with one C-call spine; its role, fibre, arm and carrier references combine with the enclosing CProgramDeclaration.programRef to identify one program/role/fibre/arm census member.',[(0,48,53)])
b.concept('implementation_binding','Implementation binding','A plugin or handler realization of a declared leaf interior, matched to program identity, role, fibre, arm and its own published seam carrier contract, with no runtime-truth authority.',[(0,110,118)])
b.concept('conformance_root','Admitted submitted conformance root','One subjectRef-bound admitted module/program/graph-function/catalog root and declared expected-coverage contract; reachability and applicable inventory fields determine the validator report scope.',[(2,220,229)])
b.concept('graph_function_composition','Graph-function composition','compose(f,g) creates a new graph function with f.inputs and g.outputs when f carries the cumulative environment required by g.',[(6,12,12),(7,16,16)])
b.concept('compute_notation','Compute epistemic notation','fn<A,B>.C, transform.C, evaluate.C and consequence.C denote knowledge states and selected abg.fn_composition contract identity over existing lawful carriers; they add no literal language extension, topology object, runtime carrier or execution target.',[(9,12,20),(10,24,29),(12,87,88)])
b.concept('ontology_partition','GTL, ABG and Product ontology partition','GTL owns authored Graph, Node, GraphVector, Context, Operator, Evaluator, Rule, GraphFunction, RefinementBoundary, CandidateFamily, ContractRef, Role, Job and Module. ABG owns admitted composition, events, Run, GraphCall, Frame, ExecutionBasis, AdvancementTransition, IterationAdvanceDecision, Continuation, payload admission/ledgers, assurance/closure and traversal/replay. Product pressure maps, acceptance lenses, lifecycle registers and domain read models remain Product projections over admitted facts.',[(11,33,68)])
b.constraint('closed_generators_and_leaf_authority',['compute_term','stage_leaf','implementation_binding'],'Every tenant represents exactly the seven C generators in an exhaustively matchable typed carrier. One C.of supplies one atomic spine, and an implementation can realize only its interior.',[(0,41,53)])
b.constraint('compute_identity_limits',['compute_term'],'C.id<A> is C<A,A> and the left/right composition identity. It projects no_declared_check only where the owning contract requires no check; it cannot satisfy a mandatory gate or complete an otherwise empty executable edge program.',[(0,55,58)],conditions=['no_declared_check requires an owning contract that demands no check.'])
b.constraint('flat_typed_compute_composition',['compute_term'],'C.compose<A,B,D> is closed and associative. Nested syntax flattens by default into ordered C.of leaves within one declared boundary. Input/output mismatch is a host type error where decidable and otherwise a typed GTL-validator gap.',[(0,60,64)])
b.constraint('edge_record_roles',['compute_term','stage_leaf'],'C.edge records transform, evaluate and consequence fields as atomic direct C.of leaves with matching literal roles. Wrapping/composition is outside the record. Roles are ordinary open declaration data; other nonempty roles are permitted, but every open program names exactly one result-bearing role.',[(0,66,71)])
b.constraint('named_workflow_lift',['compute_term'],'Only workflow.C(GraphFunctionRef<A,B>) lifts an admitted graph-function traversal into one transparent parent-level C, preserving the reference-declared A,B pair and yielding sub_traversal evidence. Raw validation proves resolution, not equality to a child published wire contract without an admitted outer-contract identity. Anonymous nesting creates no frame or monad boundary.',[(0,73,82)])
b.constraint('batch_identity_cardinality',['compute_term','stage_leaf'],'C.batch groups a nonempty ordered task family with equal input/output carriers and per-task result cardinality. Each invoking task retains one spine and one cardinality judgment; the parent grouping reference has no authority. Program cardinality stays the common per-task cardinality, not aggregate many. Distribution over composition requires equal-length compatible families paired by stable list position; task identity, evidence and judgments never collapse into one call.',[(0,84,93)],conditions=['Pointwise distribution requires equal-length compatible ordered task families.'])
b.constraint('retry_contract_boundary',['compute_term'],'C.retry preserves input/output contract, uses a positive declared budget and closes attempts under the single declared retryable-failure allowlist. It neither creates per-fibre error algebras nor authorizes undeclared repair.',[(0,95,98)])
b.constraint('role_fibre_separation',['compute_term','stage_leaf'],'Stage roles are open program data; fibres are exactly F_D, F_P and F_H. Lawful substitution changes interior and evidence class only, preserving topology, program membership and spine kinds/order/count. Validator, HoG and ABG preserve the declared fibre; observed behavior cannot reclassify F_P as F_D. Prior F_P-to-F_D replacement requires declaration versioning and tuner/equivalence annealing.',[(0,100,108)])
b.constraint('binding_contract_separation',['implementation_binding','compute_term'],'Implementation matching includes program/role/fibre/arm. GTL validates C carrier continuity separately from each implementation matching its seam contract; generic transport carriers must not be equated to domain C carrier references. Public/admitted bindings confer no event emission, traversal selection, continuation, ledger or closure authority. ABG admits results and owns resulting runtime truth.',[(0,110,118)])
b.constraint('no_compiled_execution_authority',['compute_term','implementation_binding'],'The admitted GTL program, C declaration, GraphFunction templates and implementation bindings fully declare execution. Reject abg.hog_program, catalog/ref/ladder variants, generated handler-program declarations and equivalent compiled runtime programs as executable authority. Bindings identify only declared leaf seams; opaque extension data gains no conventional runtime meaning.',[(0,120,127)])
b.constraint('native_type_maximum',['compute_term'],'Use native static type/API capabilities to the full extent they can decide law, including discriminated unions, generic I/O, opaque/nominal admitted states, exhaustive matching, constructor-only creation and role/fibre/host-indexed bindings. Do not erase locally decidable types into strings or bags by deferring to the validator.',[(0,129,134)])
b.constraint('canonical_admission_states',['compute_term'],'Authored GTL is canonical pure data. Native callers use typed constructors; files, generated/package input and API payloads use raw admission with the same sort/relation judgments. Authored, admitted, validated and runtime states stay distinct. A deterministic native constructor is lawful only if serialization/raw readmission preserves exact value and digest; its loops, branches and strings gain no authority and cannot consult ambient/runtime truth.',[(0,136,145)])
b.constraint('semantic_gap_ownership',['compute_term','conformance_root'],'The validator decides closed facts beyond local types: decoded data, root-reachable references, program/catalog membership, carriers, cardinality, constructor coverage and seam declaration completeness. Runtime admission decides environmental availability and probabilistic result facts. Lawful unrealized terms return semantic_not_realized; unresolved named references return invalid_program. Neither may silently lower to another term or compiled plan.',[(0,147,155)])
b.constraint('diagnostics_do_not_repair',['compute_term'],'C conformance failures carry stable diagnostic identity, subject path, governing axiom/requirement references, evidence and admissible repair moves. Execution-declaration admission carries typed refusal prefix/reason before effects. Rich C diagnostics name expected/actual sort or relation; generic diagnostics may use stable rule, message, evidence and repair fields. Suggested constructors, surfaces, reference corrections or constitutional re-entry do not select, perform or authorize repair.',[(0,157,165)])
b.constraint('validate_before_effect',['compute_term','stage_leaf'],'Local type/admission failures and unresolved semantic gaps stop before worker/plugin calls, archive writes, traversal, successful assessment or closure. Diagnostic fail-closed events may report refusal and terminal stop. HoG traverses original admitted terms only and cannot parse new meaning, infer behavioral types or repair declarations. Preserve every stage, order, role, fibre, arm, carrier and result-bearing designation. HoG/ABG preparation, result admission, evidence binding and materialization may surround a stage only as subordinate transitions, never replace/reorder/rename/count as authored membership or a rival plan.',[(0,167,178)],exceptions=['Diagnostic fail-closed events may report the refusal and terminal stop.'])
b.constraint('conformance_corpus_obligation',['compute_term'],'Pair positive/negative LLM-authored programs with exact expected diagnostics covering sort coercion, interfaces, role/fibre and implementation mismatch, illegal declaration hosts, duplicate authority, malformed serialized data, missing root-required declarations, inferred undeclared terms, every realized law and stable semantic_not_realized for lawful unrealized constructors.',[(0,180,187)])
b.constraint('probabilistic_output_admission',['implementation_binding'],'F_P transform, runtime-failure and live-evaluator outputs remain data until ABG checks closed schemas, required identities/evidence references and cross-field invariants. Attached artifacts admit base envelopes and closed assessment rows; declared artifact schemas govern domain extensions. Malformed outputs are blocked/rejected, and incomplete/contradictory evaluation yields retry or blocked truth, never closure by omission. Raw diagnostics may remain. This is output validation, not hostile-process protection.',[(0,189,198)])
b.constraint('desktop_trust_boundary',['implementation_binding','compute_term'],'The specified single-developer desktop model trusts in-process native code and values returned by published typed constructors; it does not demand protection against hostile process code, reflection, forged local objects, filesystem attackers or cryptographic substitution. Reject malformed authored GTL at the earliest capable type/raw/lint/validator boundary. F_P external data still requires result-schema and contradiction checks before accepted assessment/closure; raw observations/diagnostics and non-close retry truth may remain. This family owns matching to the seam; ABG plugin/result requirements own returned schemas.',[(1,202,216)])
b.constraint('conformance_is_root_bounded',['conformance_root'],'Check every declaration reachable from the admitted subjectRef root and report required missing rows relative to applicable inventory fields in its bound expected-coverage contract. Execution checks prove declared-reference completeness and membership; authoritative Product/install root and complete release manifest belong to separate release contracts.',[(2,220,229)])
b.constraint('canonical_algebra_equations',['compute_term'],'For all well-typed terms with agreeing named boundaries and effects: C.id is left/right identity, C.compose is associative, workflow.C preserves the reference-declared A,B, retry preserves its argument contract, batch distributes pointwise over equal-length ordered families, and fibre substitution preserves spine shape. Equality means admitted identity plus normalized canonical semantic data, never host object identity. Child GraphFunction equality requires an admitted outer-contract relation; workflow.C cannot synthesize one.',[(3,233,250)],conditions=['Terms are well typed and named boundaries and effects agree.','Child wire-contract equality requires its admitted language-data relation.'])
b.constraint('nonconformance_conditions',['compute_term','conformance_root'],'A toolchain is nonconforming if it relies on prose to prevent a type/validator-decidable category error, permits root-required module/catalog/coverage declarations to be absent, lets a runner interpret unregistered declarations, or permits invalid effects before diagnostics.',[(4,254,259)])
b.constraint('graph_composition_semantics',['graph_function_composition'],'Composition is associative, has an interface-preserving left/right identity and stays replayable with structure/truth reconstructible from declarations and runtime truth. Deterministically propagate/merge visible effects, tags and structured declarations; fail closed on conflicting structured values instead of inventing semantics.',[(7,18,26)])
b.constraint('composition_environment_conservation',['graph_function_composition'],'Preserve cumulative carried environment immutably. Upstream bindings remain available unless the composition explicitly narrows the contract. Fail closed for missing downstream requirements, structural mismatch or conflicting carried outputs; never silently overwrite prior environment truth.',[(7,28,32)],exceptions=['Explicit contract narrowing may reduce available carried bindings.'])
b.constraint('explicit_type_wiring',['graph_function_composition'],'Distinguish port identity from type contract. Exact name-and-contract composition remains lawful but is not exclusive when explicit wiring is declared. Differently named endpoints compose only when declared GTL type law proves the provided type satisfies the required type. Unknown references, weakened obligations or ambiguous wiring fail closed; similar names/tags/schema strings/prose prove no equivalence.',[(7,34,46)],conditions=['Differently named endpoints need explicit wiring and declared type-law satisfaction.'])
b.relation('implementation_realizes_leaf','realizes_interior','implementation_binding','stage_leaf','A matched implementation realizes only the interior of its one declared C-call leaf and supplies no runtime authority.',[(0,48,53),(0,110,118)],True)
b.relation('notation_over_ontology','describes_knowledge_over','compute_notation','ontology_partition','Notation describes epistemic states over the existing ontology without creating carriers; Product interpretations stay projections over ABG facts.',[(9,12,20),(11,65,68)],False)
b.constraint('epistemic_order',['compute_notation'],'The declared flow is A -> transform.C -> candidate/evidence references -> evaluate.C -> finding references -> ABG admission -> ABG event/ledger/assurance/traversal projections -> consequence.C -> Product read-model interpretation -> B or lawful continuation. Candidate and finding production is not admission.',[(12,72,88)])
b.residual('execution_inventory_limit','conformance_root','The current coverage carrier does not express a total expected execution-declaration inventory.','Root/reference checks alone cannot establish complete release execution coverage; authoritative Product/install manifest binding remains separate.',[(2,225,229)])
b.residual('child_contract_identity_dependency','named_workflow_lift','An admitted reference may resolve without a supplied admitted identity equating its carrier pair to the child published wire contract.','Withhold that equality and preserve the lift contract rather than infer it.',[(0,73,82),(3,248,250)])
b.residual('external_result_schema','probabilistic_output_admission','The complete returned-output schema belongs to applicable ABG plugin/result and selected artifact-schema requirements outside this supplied section.','The admission obligation is retained without inventing result fields or executing schema admission.',[(1,208,216)])
for i in [5,8]: b.disposition(i,'omitted','Header title/status/date/category and derivation links are metadata only here; referenced authorities are not imported or treated as the current method.',[])
for i in [0,1,2,3]: b.disposition(i,'residual','Preserves material laws and refusal distinctions with explicit unresolved wire-identity, result-schema or inventory limits.')
for i in [4,6,7,9,10,11,12]: b.disposition(i,'retained','Retains the substantive rule, identity, authority partition or flow in source-grounded records.')
b.finish(['Equational laws and runtime transitions are represented as propositions only; no operational family is instantiated or proved.','The submitted-root coverage contract explicitly lacks a total expected execution inventory.','Full external result schemas and admitted wire-contract identity relations must be re-entered; cross-chunk labels are not merged.','Header status/date and historical derivation links were deliberately omitted as authority claims.'])
